############ base.html ############
<!DOCTYPE html>
<html lang="{{language}}">
<head>
    <meta charset="UTF-8">
    <link rel="icon" type="image/x-icon" href="{{url_for(path='static/favicon.ico')}}">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="color-scheme" content="light dark" />
    <meta name="generator" content="Marmite" />
    {% block seo %}
    <meta property="og:title" content="{{ site.name }}">
    <meta property="og:description" content="{{ site.tagline }}">
    {% if site.card_image %}
    <meta property="og:image" content="{{url_for(path=site.card_image, abs=true)}}">
    {% endif %}
    {% if site.url %}
    <meta property="og:url" content="{{site.url}}">
    {% endif %}
    <meta property="og:type" content="website">
    <meta property="og:site_name" content="{{site.name}}">
    {% if site.extra.fediverse_verification %}
    <link rel="me" href="{{site.extra.fediverse_verification}}">
    {% endif %}
    {% endblock %}
    {%- block head %}
    <title>{% if title %}{{title}} | {%endif%}{{ site.name }}</title>
    <link rel="stylesheet" type="text/css" href="{{url_for(path='static/pico.min.css')}}">
    <link rel="stylesheet" type="text/css" href="{{url_for(path='static/marmite.css')}}">
    {% if site.extra.colorscheme %}
    <link rel="stylesheet" type="text/css" href="{{url_for(path='static/colorschemes/' ~ site.extra.colorscheme ~ '.css')}}">
    {% endif %}
    <link rel="stylesheet" type="text/css" href="{{url_for(path='static/custom.css')}}">
    {% endblock -%}
    {%- block feeds %}
    {%include 'base_feeds.html' ignore missing%}
    {% endblock %}
    {% if htmlhead is defined %}
    {{ htmlhead }}
    {% endif %}
</head>
<body>
    {% if announce is defined %}
    <div class="container-fluid announcement-wrapper">
        <div class="announcement">{{ announce }}</div>
    </div>
    {% endif %}
    <main class="container">
        {% if header is defined %}
           {{ header}}
        {% else %}
        <header class="header-content">
            <nav class="header-nav">
                <ul class="header-name">
                    <li>
                        <hgroup class="h-card">
                            <h2>
                                <a href="{{url_for(path='')}}" class="contrast p-name u-url">
                                    {% if site.logo_image %}
                                        <img src="{{url_for(path=site.logo_image)}}" alt="{{ site.name }}" class="u-photo">
                                    {% else %}
                                        {{ site.name }}
                                    {% endif %}
                                </a>
                            </h2>
                            {% if site.tagline %} <p class="p-note">{{ site.tagline }}</p> {% endif %}
                        </hgroup>
                    </li>
                </ul>
                <button id="menu-toggle" class="hamburger">&#9776;</button>

                <ul class="header-menu" id="header-menu">
                    {% for item in menu %}
                      {% set name = item.0 %}
                      {% set url = item.1 %}
                    <li>
                        {% if current_page and current_page == url %}
                        <button class="menu-item active selected">{{name | safe }}</button>
                        {% else %}
                        <a class="menu-item secondary" {% if url is starting_with("http") %} href="{{url}}" target="_blank" {% else %} href="{{url_for(path=url)}}"{% endif %}>{{ name | safe }}</a>
                        {% endif %}
                    </li>
                    {% endfor %}
                    {% if site.extra.colormodetoggle %}
                        <li><span class="theme-toggle secondary" title="dark mode">&#9789;</span></li>
                    {% endif %}
                    {% if site.enable_search %}
                    <li><a href="#" id="search-toggle" class="secondary" title="Search (Ctrl + Shift + F)"> <span class="search-txt">Search</span><span class="search-magnifier"></span></a></li>
                    {% endif %}
                    <div class="underline"></div>
                </ul>
            </nav>
            {% if site.enable_search %}
            <div class="marmite-background-overlay" id="overlay-close"></div>
            <div class="marmite-search-bar hidden">
                <span>{{site.search_title}}</span>
                <button class="marmite-close-button" id="search-close">X</button>
                <input placeholder="Search" id="marmite-search-input" />
                <div class="marmite-search-bar-result">
                    <ul id="marmite-search-bar-result"></ul>
                </div>
            </div>
            {% endif %}
        </header>
        {% endif %}
        <section class="main-content">
            {% block main -%}{%- endblock %}
        </section>
        {% if footer is defined %}
           {{ footer}}
        {% else %}
        <footer class="footer-content grid">
            {{ site.footer | safe }}
            {% if site.extra.colorscheme_toggle %}
            <div class="colorscheme-toggle-div">
                colorscheme: <select name="colorscheme" class="colorscheme-toggle"><option value="default">default</option></select>
                <span class="theme-toggle secondary" title="dark mode">&#9789;</span>
            </div>
            {% endif %}
        </footer>
        {% endif %}
    </main>
    {%- block tail %}
    <script src="{{url_for(path='static/marmite.js')}}"></script>
    <script src="{{url_for(path='static/custom.js')}}"></script>
    {% if site.enable_search %}
    <script type="module" src="{{url_for(path='static/search.js')}}"></script>
    {% endif %}
    {% if site.extra.colorscheme_toggle %}    
    <script type="application/javascript" >
        colorschemeSwitcher();
    </script>
    {% endif %}
    {% if site.extra.colormode %}
        <script type="application/javascript">
            // If there is already a scheme saved in localstorage, load that, else load config
            if (themeSwitcher.scheme == "auto") {
                themeSwitcher.scheme = "{{ site.extra.colormode }}";
                themeSwitcher.updateIcon();
            }
        </script>
    {% endif %}
    {% endblock -%}
    {% if htmltail is defined %}
    {{ htmltail }}
    {% endif %}
</body>
</html>
############ content.html ############
{% extends "base.html" %}

{% block seo %}
<meta property="og:title" content="{{content.title}}">
{% if content.description %}
<meta property="og:description" content="{{ content.description | replace(from='"', to="") | truncate(length=100, end="...") }}">
{% else %}
<meta property="og:description" content="{{ content.html | striptags | trim_start_matches(pat=content.title) | truncate(length=100, end="...") }}">
{%- endif %}
{% if content.card_image %}
<meta property="og:image" content="{{url_for(path=content.card_image, abs=true)}}">
{% elif site.card_image %}
<meta property="og:image" content="{{url_for(path=site.card_image, abs=true)}}">
{% endif %}
{% if site.url %}
<meta property="og:url" content="{{url_for(path=content.slug, abs=true)}}.html">
{% endif %}
<meta property="og:type" content="article">
<meta property="og:site_name" content="{{site.name}}">
{% if content.date %}
<meta property="article:published_time" content="{{content.date | date(format=' %+')}}">
{% endif %}
{% if site.url and content.authors %}
<meta property="article:author" content="{{url_for(path='author-' ~ content.authors.0 ~ '.html', abs=true)}}">
{% endif %}

{% include "json_ld_content.html" ignore missing%}
{% endblock %}

{% block head %}
{{ super() }}
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.10.0/styles/github.min.css" id="highlightjs-theme" />
{%if content.extra.math %}
<script type="text/x-mathjax-config">
  MathJax.Hub.Config({tex2jax: {inlineMath: [['$','$'], ['\\(','\\)']]}});
</script>
<script type="text/javascript" src="https://cdn.mathjax.org/mathjax/latest/MathJax.js?config=TeX-AMS-MML_HTMLorMML">
</script>
{% endif %}

{% endblock %}


{% block main %}

{% if content.banner_image %}
<div class="content-banner-image" style="background-image: url({{content.banner_image}});"></div>
{% endif %}

<article class="h-entry">
  <data class="p-name" value="{{ content.title }}"></data>
  <a class="u-url" href="{{url_for(path=content.slug ~ '.html')}}" style="display: none;"></a>
  {% if content.date %}
  <time class="dt-published" datetime="{{ content.date | date(format='%+') }}" style="display: none;">{{ content.date | default_date_format }}</time>
  {% endif %}

  {% if content.stream == "draft" %}
  <div class="draft-warning" style="background-color: #fff3cd; border: 1px solid #ffeaa7; border-radius: 4px; padding: 12px; margin-bottom: 20px; color: #856404;">
    <strong>M-bM-^ZM- M-oM-8M-^O Draft Post:</strong> This post is a draft and may not be complete yet.
  </div>
  {% endif %}

  {% include "content_title.html" ignore missing %}
  {% if content.series %}
  <div class="content-series">
    <p><small>Published as part of '<a href="{{ url_for(path='series-' ~ content.series ~ '.html') }}">{{ series_display_name(series=content.series) }}</a>' series.</small></p>
  </div>
  {% endif %}
  {% if content.toc %}
  <div class="content-toc">
    <a href="#" id="toc"></a>
    <details>
    <summary>M-pM-^_M-^WM-^RM-oM-8M-^O</summary>
    {{ content.toc }}
    </details>
  </div>
  {% endif %}

  <div class="content-html e-content">{{ content.html }}</div>
  {% if content.date %}
  <footer class="data-tags-footer">

    <div class="content-authors-flex">
      <div class="content-authors-full">
        {% include "content_authors.html" ignore missing %}
      </div>

      <div class="date-tags-container">
        <div class="content-date">
          {% include "content_date.html" ignore missing %}
          {% if content.stream and content.stream != "index" %}
          <div class="content-stream">
            {% set slug = content.stream | trim | slugify %}
            {% set link = slug ~ ".html"%}
            <small><a href="{{url_for(path=link)}}">{{ stream_display_name(stream=content.stream) }}</a></small>
          </div>
          {% endif %}
        </div>

        <ul class="content-tags">
          {% for tag in content.tags %}
          {% set slug = "tag-" ~ tag | trim | slugify %}
          {% set link = slug ~ ".html"%}
          <li><a href="{{url_for(path=link)}}" class="p-category">{{ tag }}</a></li>
          {% endfor %}
        </ul>
      </div>
    </div>
  </footer>
  {% endif %}
</article>

{% if site.enable_related_content and not content.series %}
{% if content.back_links %}
<article>
  Back-links
  <ul>
    {% for item in content.back_links | slice(end=10) %}
    <li><a href="{{url_for(path=item.slug ~ '.html')}}">{{item.title}}</a></li>
    {% endfor %}
  </ul>
</article>
{% endif %}

{% if content.tags %}
  {# Only the first tag for now #}
  {% set tag = content.tags[0] %}
  {% set tag_slug = tag | slugify %}
  {% set related_content = site_data.tag.map[tag_slug] %}
  {% if related_content | length > 1 %}
  <article>
    Related {{tag}} content
    <ul>
      {% for item in related_content | sort(attribute="date") | reverse | slice(end=5) %}
      {% if item.slug == content.slug or item in content.back_links %}
      {% continue %}
      {% endif %}
      <li><a href="{{url_for(path=item.slug ~ '.html')}}">{{item.title}}</a></li>
      {% endfor %}
    </ul>
  </article>
  {% endif %}
{% endif %}
{% endif %}

{% if site.show_next_prev_links and (content.previous or content.next) %}
<article>
  <nav style="display: flex; justify-content: space-between;">
    <div>
      {% if content.previous %}<a href="{{url_for(path=content.previous.slug ~ '.html')}}">M-bM-^FM-^P {{ content.previous.title }}</a>{% endif %}
    </div>
    <div>
      {% if content.next %}<a href="{{url_for(path=content.next.slug ~ '.html')}}">{{ content.next.title }} M-bM-^FM-^R</a>{% endif %}
    </div>
  </nav>
</article>
{% endif %}

{% if comments is defined %}
    <article>{{ comments }}</article>
{% elif site.extra.comments.source is defined and content.date %}
    {%include "comments.html" ignore missing %}
{% endif %}

{% if content.source_path is string and (site.publish_md or site.source_repository) %}
<article>
<div class="content-source">
  {% set source_url = source_link(content=content) %}
  {% if source_url %}
    <a href="{{url_for(path=source_url)}}" rel="nofollow">M-pM-^_M-^SM-^D View source</a>
  {% endif %}
</div>
</article>
{% endif %}


{% endblock %}

{% block tail %}
{{ super() }}
<script src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.10.0/highlight.min.js"></script>
<script>
  hljs.highlightAll();
</script>

{%if content.extra.mermaid %}
<script src="https://cdnjs.cloudflare.com/ajax/libs/mermaid/11.3.0/mermaid.min.js"></script>
<script>
  var config = {
    startOnLoad: true,
    theme: '{{content.extra.mermaid_theme | default(value="default") }}',
    flowchart: { useMaxWidth: false, htmlLabels: true }
  };
  mermaid.initialize(config);
  window.mermaid.init(undefined, document.querySelectorAll('.language-mermaid'));
</script>
{% endif %}
{% endblock %}
